<#
  Fix-CrashRecoveryAndFuelPricing.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  This replaces the earlier version of this script - the earlier one
  included a paid Anthropic API call for a daily auto-check. This version
  drops that entirely: no API key needed, no cost, no scheduled job. Fuel
  pricing is 100% manual - you type today's price per litre into the admin
  panel and click Update. Nothing runs automatically.

  PART 1 - CRASH RECOVERY
  The "Application error: a client-side exception has occurred" screen you
  hit wasn't the pickup geofence or the map-link resolver - both were
  checked directly and are correctly guarded already (confirmed the 1000m
  radius is genuinely live in your code, and every map-link path already
  fails gracefully with a friendly message, never passing bad coordinates
  onward). That generic, unstyled text is actually Next.js's own
  last-resort message for a failed lazy-loaded JS chunk - the classic
  trigger is a browser tab left open across a fresh deploy, then trying to
  load a dynamically-imported piece (the map, in this app) whose old JS
  chunk no longer exists on the server after the new deploy. error.jsx and
  global-error.jsx already exist in this app but don't catch this specific
  failure shape, since it happens before React has anything to hand them.

  Added:
    - src\components\ChunkErrorRecovery.jsx: detects this exact failure
      (by error name/message, not by guessing) and reloads once,
      automatically, instead of leaving a dead crash screen. Wired into
      src\app\layout.js.
    - src\components\MapCanvas.jsx: now filters out any marker with a
      missing/NaN lat or lng before it ever reaches Mapbox GL JS, which
      throws synchronously on invalid coordinates - cheap insurance
      regardless of root cause.
    - src\app\send-package\step-1\page.jsx: fixed a real bug found along
      the way - a failed map-link resolution was showing the raw error
      CODE (e.g. "NO_COORDINATES_FOUND") instead of the friendly message.

  PART 2 - FUEL-PRICE-AWARE PRICING, MANUAL ONLY
  Database tables already created directly in Supabase (not part of this
  script - already live): pricing_settings (singleton row: current fuel
  price, baseline it was calibrated at, safety min/max multiplier clamps)
  and fuel_price_history (audit trail of every manual change). Admin-only
  writes via RLS, publicly readable (customers need it to get a quote).

  Design: perKm rates scale by (current fuel price / baseline), clamped.
  The flat base fee does NOT scale with fuel - it represents rider
  time/handling, not distance.

  Added/changed:
    - src\utils\pricing.js (new): shared multiplier/effective-rate calc.
    - src\app\ops-terminal\pricing\ (new): admin dashboard page + form -
      view current price/multiplier/effective rates, type a new price per
      litre and click Update, adjust baseline/safety bounds (optional,
      collapsed by default), and see recent change history. Added to the
      Ops Terminal nav under "Fuel Pricing".
    - src\app\send-package\step-2\page.jsx and
      src\app\vendor\create-delivery\page.jsx: both pricing calculators
      (they were already two separate systems before this - untouched
      otherwise) now fetch the current multiplier and apply it, falling
      back to unmultiplied static rates if the fetch fails.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  every existing file it touches to .fix-backup-crash-and-pricing\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-CrashRecoveryAndFuelPricing.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-crash-and-pricing"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying crash-recovery and manual fuel-pricing fixes:" -ForegroundColor Cyan

$b64_LAYOUT = ""
Write-FileFromBase64 "src\app\layout.js" $b64_LAYOUT

$b64_CHUNKRECOVERY = ""
Write-FileFromBase64 "src\components\ChunkErrorRecovery.jsx" $b64_CHUNKRECOVERY

$b64_MAPCANVAS = ""
Write-FileFromBase64 "src\components\MapCanvas.jsx" $b64_MAPCANVAS

$b64_SENDSTEP1 = ""
Write-FileFromBase64 "src\app\send-package\step-1\page.jsx" $b64_SENDSTEP1

$b64_SENDSTEP2 = ""
Write-FileFromBase64 "src\app\send-package\step-2\page.jsx" $b64_SENDSTEP2

$b64_VENDORCREATE = ""
Write-FileFromBase64 "src\app\vendor\create-delivery\page.jsx" $b64_VENDORCREATE

$b64_PRICINGUTIL = ""
Write-FileFromBase64 "src\utils\pricing.js" $b64_PRICINGUTIL

$b64_PRICINGPAGE = ""
Write-FileFromBase64 "src\app\ops-terminal\pricing\page.jsx" $b64_PRICINGPAGE

$b64_PRICINGFORM = ""
Write-FileFromBase64 "src\app\ops-terminal\pricing\PricingSettingsForm.jsx" $b64_PRICINGFORM

$b64_PRICINGACTIONS = ""
Write-FileFromBase64 "src\app\ops-terminal\pricing\actions.js" $b64_PRICINGACTIONS

$b64_OPSSHELL = ""
Write-FileFromBase64 "src\app\ops-terminal\OpsTerminalShell.jsx" $b64_OPSSHELL

Write-Host "`nDone. Backups saved under .fix-backup-crash-and-pricing\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
